/// Compute public-data div_rem_mixed on unsigned device limb rows.
///
/// Operands are public rank-two U32 rows of little-endian limbs,
/// with 1..=128 words (32..=4096 bits). Records device work without host reads
/// or a host wait. This public-data route does not accept cryptographic secrets
/// and makes no constant-time or performance claim.
///
/// Division returns (quotient, remainder, status): 1 success, 0 zero divisor, 2 quotient overflow.
/// Invalid rows have completely zero outputs. The divisor may be one shared row.
/// Mixed division accepts independent dividend (1..=256), divisor (1..=128)
/// and quotient (1..=256) word counts; wide/narrow division takes a double-width dividend.
///
/// # Errors
///
/// Rejects rank, dtype, shape, ownership, address limits, allocation or recording failures.
pub fn div_rem_mixed(
	left: &Matrix,
	right: &Matrix,
	quotient_words: u32,
) -> Result<(Matrix, Matrix, Matrix)> {
	let contract = crate::core::operation::cryptography::bigint::DIV_REM_MIXED;
	let operation = contract.name();
	let [rows, input_words] = match left.shape() {
		[rows, words] => [*rows, *words],
		_ => {
			return Err(Error::invalid_argument(format!(
				"{operation} requires rank-two U32 rows"
			)));
		}
	};
	let words = match right.shape() {
		[_, words] => *words,
		_ => {
			return Err(Error::invalid_argument(format!(
				"{operation} requires rank-two divisors"
			)));
		}
	};
	if left.dtype() != DType::U32
		|| !(1..=256).contains(&input_words)
		|| !(1..=128).contains(&words)
		|| right.dtype() != DType::U32
		|| (right.shape()[0] != 1 && right.shape()[0] != rows)
		|| !left.engine_handle().same_as(right.engine_handle())
		|| !(1..=256).contains(&quotient_words)
	{
		return Err(Error::invalid_argument(format!(
			"{operation} has invalid dtype, widths, shape or ownership"
		)));
	}
	let count = u32::try_from(rows)
		.map_err(|_| Error::invalid_argument(format!("{operation} batch exceeds u32")))?;
	let input_bytes = rows
		.checked_mul(input_words)
		.and_then(|n| n.checked_mul(4))
		.ok_or_else(|| {
			Error::invalid_argument(format!("{operation} input byte extent overflows usize"))
		})?;
	u32::try_from(input_bytes)
		.map_err(|_| Error::invalid_argument(format!("{operation} input byte extent exceeds u32")))?;
	let engine = left.engine_handle();
	let quotient_elements = rows
		.checked_mul(quotient_words as usize)
		.ok_or_else(|| Error::invalid_argument(format!("{operation} output extent overflows usize")))?;
	let quotient_bytes = quotient_elements.checked_mul(4).ok_or_else(|| {
		Error::invalid_argument(format!("{operation} output byte extent overflows usize"))
	})?;
	u32::try_from(quotient_bytes)
		.map_err(|_| Error::invalid_argument(format!("{operation} output byte extent exceeds u32")))?;
	let quotient = Matrix::allocate_output(
		engine,
		vec![rows, quotient_words as usize],
		quotient_elements,
		DType::U32,
	)?;
	let remainder_elements = rows
		.checked_mul(words)
		.ok_or_else(|| Error::invalid_argument(format!("{operation} output extent overflows usize")))?;
	let remainder_bytes = remainder_elements.checked_mul(4).ok_or_else(|| {
		Error::invalid_argument(format!("{operation} output byte extent overflows usize"))
	})?;
	u32::try_from(remainder_bytes)
		.map_err(|_| Error::invalid_argument(format!("{operation} output byte extent exceeds u32")))?;
	let remainder =
		Matrix::allocate_output(engine, vec![rows, words], remainder_elements, DType::U32)?;
	let status_elements = rows
		.checked_mul(1)
		.ok_or_else(|| Error::invalid_argument(format!("{operation} output extent overflows usize")))?;
	let status_bytes = status_elements.checked_mul(4).ok_or_else(|| {
		Error::invalid_argument(format!("{operation} output byte extent overflows usize"))
	})?;
	u32::try_from(status_bytes)
		.map_err(|_| Error::invalid_argument(format!("{operation} output byte extent exceeds u32")))?;
	let status = Matrix::allocate_output(engine, vec![rows], status_elements, DType::U32)?;
	if rows != 0 {
		let kernel = KernelId::CryptographyBigIntDivRemMixedU32;
		let buffers = [
			BufferBinding::read(left.storage()),
			BufferBinding::read(right.storage()),
			BufferBinding::write(quotient.storage()),
			BufferBinding::write(remainder.storage()),
			BufferBinding::write(status.storage()),
		];
		let push_constants = [
			PushConstant::U32(count),
			PushConstant::U32(words as u32),
			PushConstant::U32(input_words as u32),
			PushConstant::U32(quotient_words),
			PushConstant::U32(right.shape()[0] as u32),
		];
		let inputs = [left, right];
		let outputs = [&quotient, &remainder, &status];
		let attributes = [
			OpAttribute::UnsignedInteger {
				name: "width_bits".into(),
				value: (words * 32) as u64,
			},
			OpAttribute::UnsignedInteger {
				name: "quotient_words".into(),
				value: quotient_words as u64,
			},
		];
		engine.record_semantic(
			ComputeDispatch {
				kernel,
				buffers: &buffers,
				push_constants: &push_constants,
				workgroups: kernel.linear_workgroups(count),
			},
			SemanticDispatch {
				contract,
				inputs: &inputs,
				outputs: &outputs,
				attributes: &attributes,
			},
		)?;
	}
	Ok((quotient, remainder, status))
}

