/// Prepare a device-owned public Barrett modulus snapshot and reciprocal.
///
/// # Errors
/// Rejects dtype, rank, width, byte extents, allocation or recording failures.
pub fn setup_barrett(modulus: &Matrix) -> Result<BarrettParameters> {
	let contract = crate::core::operation::cryptography::bigint::SETUP_BARRETT;
	let [rows, words] = match modulus.shape() {
		[rows, words] => [*rows, *words],
		_ => {
			return Err(Error::invalid_argument(
				"setup_barrett requires rank-two modulus rows",
			));
		}
	};
	if modulus.dtype() != DType::U32 || !(1..=128).contains(&words) {
		return Err(Error::invalid_argument(
			"setup_barrett requires U32 modulus rows with 1..=128 words",
		));
	}
	let count =
		u32::try_from(rows).map_err(|_| Error::invalid_argument("setup_barrett batch exceeds u32"))?;
	let encoded_words = words * 2 + 3;
	let elements = rows
		.checked_mul(encoded_words)
		.ok_or_else(|| Error::invalid_argument("setup_barrett extent overflows usize"))?;
	let bytes = elements
		.checked_mul(4)
		.ok_or_else(|| Error::invalid_argument("setup_barrett bytes overflow usize"))?;
	u32::try_from(bytes).map_err(|_| Error::invalid_argument("setup_barrett bytes exceed u32"))?;
	let engine = modulus.engine_handle();
	let encoded = Matrix::allocate_output(engine, vec![rows, encoded_words], elements, DType::U32)?;
	let status = Matrix::allocate_output(engine, vec![rows], rows, DType::U32)?;
	if rows != 0 {
		let kernel = KernelId::CryptographyBigIntSetupBarrettU32;
		let buffers = [
			BufferBinding::read(modulus.storage()),
			BufferBinding::write(encoded.storage()),
			BufferBinding::write(status.storage()),
		];
		let push_constants = [PushConstant::U32(count), PushConstant::U32(words as u32)];
		let attributes = [OpAttribute::UnsignedInteger {
			name: "width_bits".into(),
			value: (words * 32) as u64,
		}];
		engine.record_semantic(
			ComputeDispatch {
				kernel,
				buffers: &buffers,
				push_constants: &push_constants,
				workgroups: kernel.linear_workgroups(count),
			},
			SemanticDispatch {
				contract,
				inputs: &[modulus],
				outputs: &[&encoded, &status],
				attributes: &attributes,
			},
		)?;
	}
	Ok(BarrettParameters {
		encoded,
		status,
		words,
	})
}

/// Reduce double-width public rows using a prepared immutable Barrett snapshot.
///
/// Returns `(output, status)`: one for success, zero for a zero modulus, two
/// when T is outside the significant-width Barrett bound T < 2^(64*k).
/// Invalid rows produce zero. The prepared modulus may have one shared row.
///
/// # Errors
/// Rejects dtype, shape, ownership, byte extents, allocation or recording failures.
pub fn reduce_barrett(left: &Matrix, parameters: &BarrettParameters) -> Result<(Matrix, Matrix)> {
	let contract = crate::core::operation::cryptography::bigint::REDUCE_BARRETT;
	let words = parameters.words;
	let [rows, input_words] = match left.shape() {
		[rows, input_words] => [*rows, *input_words],
		_ => {
			return Err(Error::invalid_argument(
				"reduce_barrett requires rank-two double-width rows",
			));
		}
	};
	let prepared = &parameters.encoded;
	if left.dtype() != DType::U32
		|| input_words != words * 2
		|| (prepared.shape()[0] != 1 && prepared.shape()[0] != rows)
		|| !left.engine_handle().same_as(prepared.engine_handle())
	{
		return Err(Error::invalid_argument(
			"reduce_barrett requires matching Engine and modulus width/batch",
		));
	}
	let count =
		u32::try_from(rows).map_err(|_| Error::invalid_argument("reduce_barrett batch exceeds u32"))?;
	let input_bytes = left
		.num_elements()
		.checked_mul(4)
		.ok_or_else(|| Error::invalid_argument("reduce_barrett input bytes overflow usize"))?;
	u32::try_from(input_bytes)
		.map_err(|_| Error::invalid_argument("reduce_barrett input bytes exceed u32"))?;
	let elements = rows
		.checked_mul(words)
		.ok_or_else(|| Error::invalid_argument("reduce_barrett output extent overflows usize"))?;
	let engine = left.engine_handle();
	let output = Matrix::allocate_output(engine, vec![rows, words], elements, DType::U32)?;
	let status = Matrix::allocate_output(engine, vec![rows], rows, DType::U32)?;
	if rows != 0 {
		let kernel = KernelId::CryptographyBigIntReduceBarrettU32;
		let buffers = [
			BufferBinding::read(left.storage()),
			BufferBinding::read(prepared.storage()),
			BufferBinding::write(output.storage()),
			BufferBinding::write(status.storage()),
		];
		let push_constants = [
			PushConstant::U32(count),
			PushConstant::U32(words as u32),
			PushConstant::U32(prepared.shape()[0] as u32),
		];
		let attributes = [OpAttribute::UnsignedInteger {
			name: "width_bits".into(),
			value: (words * 32) as u64,
		}];
		engine.record_semantic(
			ComputeDispatch {
				kernel,
				buffers: &buffers,
				push_constants: &push_constants,
				workgroups: kernel.linear_workgroups(count),
			},
			SemanticDispatch {
				contract,
				inputs: &[left, prepared],
				outputs: &[&output, &status],
				attributes: &attributes,
			},
		)?;
	}
	Ok((output, status))
}
